import { useEffect, useRef, useState, type ClipboardEvent, type DragEvent } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { ArrowDownLeft, ArrowUpRight, BadgeCheck, Check, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, CircleDollarSign, ClipboardList, Clock3, Download, FileText, Package, Plus, Search, Settings2, X } from 'lucide-react'
import { api, type InventoryRow, type Project, type PurchaseOrder, type Timecard } from '../lib/api'
import { currency, dateLabel, statusClass, todayISO } from '../lib/format'
import { EmptyState, InlineError, Kpi, MutationError, PageTitle, PanelHeading, QueryError, FormActions } from '../components/ui'
import type { View } from '../lib/types'

export function Overview({ project, projectId, canWrite = true, onNavigate, onNewPO }: { project?: Project; projectId: string; canWrite?: boolean; onNavigate: (view: View) => void; onNewPO: () => void }) {
  const queryClient = useQueryClient()
  const [range, setRange] = useState(6)
  const [chartDate] = useState(() => new Date())
  const [printOrders, setPrintOrders] = useState<PurchaseOrder[] | null>(null)
  const [editingStatus, setEditingStatus] = useState(false)
  const [uploadingPlan, setUploadingPlan] = useState(false)
  const valueHistory = useQuery({ queryKey: ['project', projectId, 'value-history'], queryFn: () => api.valueHistory(projectId) })
  const documents = useQuery({ queryKey: ['project', projectId, 'documents'], queryFn: () => api.documents(projectId) })
  const dashboard = useQuery({ queryKey: ['project', projectId, 'dashboard'], queryFn: () => api.dashboard(projectId) })
  const statuses = useQuery({ queryKey: ['project', projectId, 'status-history'], queryFn: () => api.statusHistory(projectId) })
  const orders = useQuery({ queryKey: ['project', projectId, 'purchase-orders', { page: 1, page_size: 4 }], queryFn: () => api.purchaseOrders(projectId, 1, 4) })
  const dash = dashboard.data
  const actual = Number(dash?.actual_cost || 0)
  const budget = Number(dash?.budget || 0)
  const chartMaximum = Math.max(1, budget, ...((dash?.monthly_costs || []).map(entry => Number(entry.amount))))
  const months = (() => {
    const values: { key: string; label: string; cumulative: number }[] = []
    let cumulative = 0
    const end = new Date(chartDate.getFullYear(), chartDate.getMonth(), 1)
    for (let offset = range - 1; offset >= 0; offset -= 1) {
      const monthDate = new Date(end.getFullYear(), end.getMonth() - offset, 1)
      const key = `${monthDate.getFullYear()}-${String(monthDate.getMonth() + 1).padStart(2, '0')}`
      cumulative = (dash?.monthly_costs || []).filter(entry => entry.month <= key).reduce((sum, entry) => sum + Number(entry.amount), 0)
      values.push({ key, label: monthDate.toLocaleDateString('en-US', { month: 'short' }), cumulative })
    }
    return values
  })()
  const exportReport = async () => {
    if (!dash) return
    try {
      const firstPage = await api.purchaseOrders(projectId, 1, 200)
      const allOrders = [...firstPage.items]
      for (let page = 2; page <= Math.ceil(firstPage.total / 200); page += 1) {
        const nextPage = await api.purchaseOrders(projectId, page, 200)
        allOrders.push(...nextPage.items)
      }
      setPrintOrders(allOrders)
      await new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve())))
      await document.fonts.ready
      const originalTitle = document.title
      document.title = `${project?.name || 'Project'} - Overview Report`
      window.addEventListener('afterprint', () => { document.title = originalTitle; setPrintOrders(null) }, { once: true })
      window.print()
    } catch {
      setPrintOrders(null)
      await orders.refetch()
    }
  }
  return <div className="overview-sections">
    <PageTitle eyebrow="PROJECT OVERVIEW" title={project?.name || 'Project overview'} subtitle={`${project?.location || ''} · Updated ${dash?.as_of ? new Date(dash.as_of).toLocaleDateString('en-IN') : 'today'}`} action={<div className="overview-actions">{canWrite && <button className="button-secondary" onClick={() => setEditingStatus(true)} disabled={!project?.eligible_statuses?.length}><Settings2 size={14} />Project status</button>}<button className="button-secondary export-report-action" onClick={exportReport} disabled={!dash || [dashboard, documents, statuses, valueHistory, orders].some(query => query.isFetching || query.isError)}><Download size={14} />Export report</button>{canWrite && <button className="button-primary" onClick={onNewPO}><Plus size={15} />Quick entry</button>}</div>} />
    <div className="overview-print-brand">Vridhi Constructions &amp; Designs</div>
    <div className="kpi-grid"><Kpi label="Contract value" value={currency(dash?.approved_contract_value, dash?.currency)} note="Original and approved changes" icon={<FileText size={17} />} loading={dashboard.isLoading} /><Kpi label="Actual cost" value={currency(dash?.actual_cost, dash?.currency)} note={`${budget ? Math.round(actual / budget * 100) : 0}% of approved budget used`} icon={<ArrowDownLeft size={17} />} loading={dashboard.isLoading} /><Kpi label="Open commitments" value={currency(dash?.open_commitments, dash?.currency)} note="Outstanding procurement" icon={<Clock3 size={17} />} loading={dashboard.isLoading} /><Kpi label="Projected margin" value={`${dash?.margin_percent || '0'}%`} note="Based on current records" icon={<ArrowUpRight size={17} />} loading={dashboard.isLoading} /></div>
    <QueryError error={dashboard.error} onRetry={() => void dashboard.refetch()} />
    <div className="overview-grid">
      <section className="panel"><PanelHeading title="Budget vs. actual cost" meta={`Monthly cumulative spend · ${dash?.currency || 'INR'}`} action={<select className="overview-range" aria-label="Chart date range" value={range} onChange={event => setRange(Number(event.target.value))}><option value={6}>Last 6 months</option><option value={12}>Last 12 months</option></select>} /><div className="overview-chart-wrap"><div className="overview-chart-legend"><span><i />Actual cost</span><span><i className="baseline" />Approved budget</span></div><div className="overview-chart" role="img" aria-label="Monthly cumulative actual cost against approved budget">{months.map(month => <div className="overview-bar-group" key={month.key} title={`${month.key}: ${currency(month.cumulative, dash?.currency)}`}><div className="overview-bar actual" style={{ height: `${month.cumulative / chartMaximum * 100}%` }} /><div className="overview-bar baseline" style={{ height: `${budget / chartMaximum * 100}%` }} /><span>{month.label}</span></div>)}</div><div className="overview-chart-foot"><span>Budget baseline <strong>{currency(budget, dash?.currency)}</strong></span><span>Spent to date <strong>{currency(actual, dash?.currency)}</strong></span></div></div></section>
      <section className="panel"><PanelHeading title="Cost breakdown" meta="Actual costs only · unrecorded categories are not estimated" action={<button className="button-secondary" onClick={() => onNavigate('procurement')}>Details <ArrowUpRight size={14} /></button>} /><div className="overview-mix">{['Materials', 'Labor', 'Equipment & other'].map((category, index) => { const entry = dash?.cost_breakdown?.find(value => value.category === category); const amount = entry?.recorded && entry.amount != null ? Number(entry.amount) : null; const source = category === 'Materials' ? 'Valued inventory receipts' : category === 'Labor' ? 'Contract claims and direct weekly worker records' : 'Classified equipment/other costs'; return <div className="overview-mix-row" key={category}><div className="cost-category-copy"><div><span>{category}</span><strong>{amount == null ? 'Not recorded' : currency(amount, dash?.currency)}</strong></div><small>{amount == null ? `Source: ${source}` : `Source: ${source} · actual`}</small></div><div className="overview-track"><span className={`category-${index}`} style={{ width: `${amount != null && actual ? Math.min(100, amount / actual * 100) : 0}%` }} /></div></div> })}<div className="overview-mix-total"><span>Total recorded actual cost</span><strong>{currency(actual, dash?.currency)}</strong></div><div className="overview-mix-total commitments-total"><span>Open purchase-order commitments · not actual cost</span><strong>{currency(dash?.open_commitments, dash?.currency)}</strong></div></div></section>
    </div>
    <section className="panel table-panel"><PanelHeading title={printOrders ? 'Purchase order register' : 'Recent purchase orders'} meta={printOrders ? `${printOrders.length} purchase orders · order date, newest first` : 'Latest procurement activity for this project'} action={!printOrders && <button className="button-secondary" onClick={() => onNavigate('procurement')}>View all <ArrowUpRight size={14} /></button>} /><OrderTable orders={printOrders || orders.data?.items || []} loading={!printOrders && orders.isLoading} compact /><QueryError error={!printOrders ? orders.error : null} onRetry={() => void orders.refetch()} /></section>
    <section className="panel table-panel"><PanelHeading title="Plan documents" meta="Approval documents and updated plans · newest first" action={canWrite && project && ['Planning', 'Active', 'On Hold'].includes(project.status) && <button className="button-primary" onClick={() => setUploadingPlan(true)}><Plus size={15} />Upload plan document</button>} /><div className="table-scroll"><table className="data-table"><thead><tr><th>Document</th><th>Uploaded</th><th>Uploaded by</th><th className="numeric">Current value (₹)</th><th className="numeric">New estimate (₹)</th><th>Comment</th><th>File</th></tr></thead><tbody>{documents.isLoading ? <tr><td colSpan={7}><div className="loading-line" /></td></tr> : documents.data?.items.length ? documents.data.items.map(file => <tr key={file.id}><td><strong>{file.filename}</strong><div className="muted-cell">{file.content_type}</div></td><td>{new Date(file.uploaded_at).toLocaleString('en-IN')}</td><td>{file.uploaded_by}</td><td className="numeric">{file.current_value != null ? currency(file.current_value, project?.currency) : 'Not recorded'}</td><td className="numeric">{file.new_estimate != null ? currency(file.new_estimate, project?.currency) : 'Not recorded'}</td><td className="overview-comment">{file.comment || 'No comment'}</td><td><a className="button-secondary" href={`/api/v1/projects/${projectId}/documents/${file.id}/file`} download><Download size={14} />Download</a></td></tr>) : <tr><td colSpan={7}><EmptyState title="No plan documents have been uploaded" note="" /></td></tr>}</tbody></table></div><QueryError error={documents.error} onRetry={() => void documents.refetch()} /></section>
    <section className="panel table-panel"><PanelHeading title="Project value history" meta="Estimate changes from uploaded plans · newest first" /><div className="table-scroll"><table className="data-table"><thead><tr><th>Change date</th><th>Existing value</th><th>New estimate</th><th>Changed by</th><th>Plan document / comment</th></tr></thead><tbody>{valueHistory.data?.items.length ? valueHistory.data.items.map(entry => <tr key={entry.id}><td>{new Date(entry.changed_at).toLocaleString('en-IN')}</td><td>{currency(entry.previous_value, dash?.currency)}</td><td>{currency(entry.new_value, dash?.currency)}</td><td>{entry.changed_by}</td><td><strong>{entry.filename}</strong><div className="overview-comment">{entry.comment}</div></td></tr>) : <tr><td colSpan={5}><EmptyState title={valueHistory.isLoading ? 'Loading value history...' : 'No plan-based estimate changes recorded'} note="" /></td></tr>}</tbody></table></div><QueryError error={valueHistory.error} onRetry={() => void valueHistory.refetch()} /></section>
    <section className="panel table-panel overview-status"><PanelHeading title="Project status" meta="Status changes and user comments · newest first" action={canWrite && <button className="button-secondary" onClick={() => setEditingStatus(true)} disabled={!project?.eligible_statuses?.length}><Settings2 size={14} />Update status</button>} /><div className="overview-status-body"><div className="overview-current-status"><span className={`status-dot ${statusClass(project?.status || 'Planning')}`} /><span>Current status: <strong>{project?.status}</strong></span></div></div><div className="table-scroll"><table className="data-table"><thead><tr><th>Current status</th><th>Status before</th><th>Date it changed</th><th>Who updated</th><th>Comments</th></tr></thead><tbody>{statuses.isLoading ? <tr><td colSpan={5}><div className="loading-line" /></td></tr> : statuses.data?.items.length ? statuses.data.items.map(entry => <tr key={entry.id}><td><span className={`status-pill ${statusClass(entry.new_status)}`}>{entry.new_status}</span></td><td>{entry.previous_status || 'Not recorded'}</td><td>{new Date(entry.occurred_at).toLocaleString('en-IN')}</td><td>{entry.actor.name}</td><td className="overview-comment">{entry.comment || 'No comment'}</td></tr>) : <tr><td colSpan={5}><EmptyState title="No status comments recorded yet" note="" /></td></tr>}</tbody></table></div><QueryError error={statuses.error} onRetry={() => void statuses.refetch()} /></section>
    {canWrite && editingStatus && project && <ModalFrame title="Update project status" onClose={() => setEditingStatus(false)}><ProjectStatusForm key={project.id} project={project} onCancel={() => setEditingStatus(false)} onSaved={async () => { await queryClient.invalidateQueries({ queryKey: ['projects'] }); await queryClient.invalidateQueries({ queryKey: ['project', projectId, 'status-history'] }); setEditingStatus(false) }} /></ModalFrame>}
    {canWrite && uploadingPlan && dash && <ModalFrame title="Upload plan document" dismissOnBackdrop={false} onClose={() => setUploadingPlan(false)}><PlanUploadForm key={projectId} projectId={projectId} currentValue={dash.approved_contract_value} onCancel={() => setUploadingPlan(false)} onSaved={async () => { await queryClient.invalidateQueries({ queryKey: ['project', projectId] }); await queryClient.invalidateQueries({ queryKey: ['projects'] }); setUploadingPlan(false) }} /></ModalFrame>}
  </div>
}

export function ProjectStatusForm({ project, onCancel, onSaved }: { project: Project; onCancel: () => void; onSaved: () => void }) {
  const eligibleStatuses = project.eligible_statuses || []
  const [status, setStatus] = useState(eligibleStatuses[0] || '')
  const [comment, setComment] = useState('')
  const [holdReason, setHoldReason] = useState('')
  const [confirmComplete, setConfirmComplete] = useState(false)
  const mutation = useMutation({ mutationFn: () => api.updateProjectStatus(project, { status, comment, hold_reason: holdReason, confirm_complete: confirmComplete }), onSuccess: onSaved })
  return <form className="form-grid" onSubmit={event => { event.preventDefault(); if (eligibleStatuses.includes(status)) mutation.mutate() }}><div className="full overview-current-status">Current status: <strong>{project.status}</strong></div><label className="field full">Project status<select required value={status} onChange={event => setStatus(event.target.value)}>{eligibleStatuses.map(value => <option key={value}>{value}</option>)}</select></label><label className="field full">Comment<textarea required value={comment} onChange={event => setComment(event.target.value)} /></label>{status === 'On Hold' && <label className="field full">Hold reason<input required value={holdReason} onChange={event => setHoldReason(event.target.value)} /></label>}{status === 'Completed' && <label className="full overview-confirm"><input required type="checkbox" checked={confirmComplete} onChange={event => setConfirmComplete(event.target.checked)} />Confirm project completion</label>}<MutationError error={mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending || !eligibleStatuses.length} submit="Update status" /></form>
}

export function PlanUploadForm({ projectId, currentValue, onCancel, onSaved }: { projectId: string; currentValue: string; onCancel: () => void; onSaved: () => void }) {
  const [file, setFile] = useState<File | null>(null)
  const [newEstimate, setNewEstimate] = useState('')
  const [comment, setComment] = useState('')
  const [fileError, setFileError] = useState('')
  const mutation = useMutation({ mutationFn: () => api.uploadPlan(projectId, file!, comment, currentValue, newEstimate), onSuccess: onSaved })
  const acceptFile = (candidate?: File) => {
    if (!candidate) return
    if (!/\.(pdf|png|jpe?g|docx)$/i.test(candidate.name)) { setFileError('Choose a PDF, PNG, JPG, or DOCX file.'); return }
    if (!candidate.size || candidate.size > 10 * 1024 * 1024) { setFileError('Choose a non-empty file no larger than 10 MB.'); return }
    setFileError('')
    setFile(candidate)
  }
  return <form className="form-grid" onSubmit={event => { event.preventDefault(); if (!file) { setFileError('Choose a plan document.'); return } mutation.mutate() }}>
    <label className="field">Current project value (₹)<input disabled value={new Intl.NumberFormat('en-IN', { maximumFractionDigits: 2 }).format(Number(currentValue))} /></label>
    <label className="field">New estimated value (₹)<input required type="number" min="0" step="0.01" value={newEstimate} disabled={mutation.isPending} onChange={event => setNewEstimate(event.target.value)} placeholder="Enter revised estimate" /></label>
    <label className="field full">Plan approval or updated plan<div className="native-file-row" tabIndex={0} onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); acceptFile(event.dataTransfer.files[0]) }} onPaste={event => { const image = Array.from(event.clipboardData.items).find(item => item.type.startsWith('image/'))?.getAsFile(); if (image) { event.preventDefault(); acceptFile(new File([image], `pasted-plan-${Date.now()}.${image.type === 'image/jpeg' ? 'jpg' : 'png'}`, { type: image.type })) } }}><input type="file" accept=".pdf,.png,.jpg,.jpeg,.docx" disabled={mutation.isPending} onChange={event => acceptFile(event.target.files?.[0])} /></div>{file && <small className="field-hint">{file.name}</small>}<small className="field-hint">PDF, PNG, JPG, or DOCX · max 10 MB</small></label>
    <label className="field full">Comment (optional)<textarea maxLength={500} value={comment} disabled={mutation.isPending} onChange={event => setComment(event.target.value)} placeholder="Describe this approval or plan update" /></label>
    {fileError && <div className="form-error full" role="alert">{fileError}</div>}<MutationError error={mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending} submit="Upload document" />
  </form>
}

export function Procurement({ projectId, search, setSearch, onNew, onEdit, onPayment, onHistory }: { projectId: string; search: string; setSearch: (value: string) => void; onNew: () => void; onEdit: (order: PurchaseOrder) => void; onPayment: (order: PurchaseOrder) => void; onHistory: (order: PurchaseOrder) => void }) {
  const [paymentStatus, setPaymentStatus] = useState('')
  const [pagination, setPagination] = useState<{ projectId: string; search: string; paymentStatus?: string; page: number; size: number }>({ projectId, search, paymentStatus, page: 1, size: 20 })
  const [printOrders, setPrintOrders] = useState<PurchaseOrder[] | null>(null)
  const page = pagination.projectId === projectId && pagination.search === search && pagination.paymentStatus === paymentStatus ? pagination.page : 1
  const pageSize = pagination.size
  const summary = useQuery({ queryKey: ['project', projectId, 'procurement-summary'], queryFn: () => api.procurementSummary(projectId) })
  const orders = useQuery({ queryKey: ['project', projectId, 'purchase-orders', { search, paymentStatus, page, pageSize }], queryFn: () => api.purchaseOrders(projectId, page, pageSize, search, paymentStatus) })
  const visibleOrders = (orders.data?.items || []).filter(order => !paymentStatus || order.payment_status === paymentStatus)
  const total = orders.data?.total || 0
  const pages = Math.max(1, Math.ceil(total / pageSize))
  const changePage = (next: number) => setPagination({ projectId, search, paymentStatus, page: next, size: pageSize })
  const totals = summary.data
  const exportReport = async () => {
    try {
      const firstPage = await api.purchaseOrders(projectId, 1, 200)
      const allOrders = [...firstPage.items]
      for (let pageNumber = 2; pageNumber <= Math.ceil(firstPage.total / 200); pageNumber += 1) {
        const pageResult = await api.purchaseOrders(projectId, pageNumber, 200)
        allOrders.push(...pageResult.items)
      }
      setPrintOrders(allOrders)
      await new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve())))
      await document.fonts.ready
      const previousTitle = document.title
      document.title = `Project ${projectId} - Procurement Register`
      window.addEventListener('afterprint', () => { document.title = previousTitle; setPrintOrders(null) }, { once: true })
      window.print()
    } catch {
      setPrintOrders(null)
    }
  }
  return <><PageTitle eyebrow="PURCHASING" title="Procurement" subtitle="Purchase orders and vendor commitments" action={<div className="overview-actions"><button className="button-secondary" onClick={exportReport} disabled={summary.isFetching || summary.isError || orders.isFetching || orders.isError}><Download size={14} />Export report</button><button className="button-primary" onClick={onNew}><Plus size={16} />New purchase order</button></div>} /><div className="kpi-grid four"><Kpi label="Purchase orders" value={String(totals?.order_count ?? '—')} note="For this project" icon={<ClipboardList size={17} />} loading={summary.isLoading} /><Kpi label="Total ordered" value={currency(totals?.total_ordered, totals?.currency)} note="Purchase order value" icon={<Package size={17} />} loading={summary.isLoading} /><Kpi label="Total paid" value={currency(totals?.total_paid, totals?.currency)} note="Payment ledger" icon={<Check size={17} />} loading={summary.isLoading} /><Kpi label="Outstanding balance" value={currency(totals?.outstanding_balance, totals?.currency)} note="Vendor payments due" icon={<CircleDollarSign size={17} />} loading={summary.isLoading} /></div>{summary.error && <InlineError error={summary.error} onRetry={() => void summary.refetch()} />}<section className="panel table-panel procurement-register"><PanelHeading title={printOrders ? 'Purchase order register' : 'Purchase order register'} meta={printOrders ? `${printOrders.length} purchase orders · order date, newest first` : 'Order date, newest first · payment state does not affect order'} action={!printOrders && <div className="register-tools"><div className="register-status-filter" role="group" aria-label="Filter purchase orders by payment status"><span className="register-filter-hint">Status</span><button type="button" className={`register-status-option${paymentStatus === '' ? ' selected' : ''}`} aria-pressed={paymentStatus === ''} onClick={() => { setPaymentStatus(''); setPagination({ projectId, search, paymentStatus: '', page: 1, size: pageSize }) }}>All</button>{(['Paid', 'Partially paid', 'Pending'] as const).map(status => <button key={status} type="button" className={`register-status-option${paymentStatus === status ? ' selected' : ''}`} aria-label={`Filter ${status} purchase orders`} aria-pressed={paymentStatus === status} onClick={() => { setPaymentStatus(status); setPagination({ projectId, search, paymentStatus: status, page: 1, size: pageSize }) }}><StatusMark status={status} /><span>{status}</span></button>)}</div><div className="search-wrap"><Search size={16} /><input placeholder="Search vendor, item or PO" value={search} onChange={event => { setSearch(event.target.value); setPagination({ projectId, search: event.target.value, paymentStatus, page: 1, size: pageSize }) }} /></div></div>} /><OrderTable orders={printOrders || visibleOrders} loading={!printOrders && orders.isLoading} onEdit={printOrders ? undefined : onEdit} onPayment={printOrders ? undefined : onPayment} onHistory={printOrders ? undefined : onHistory} /><div className="register-pagination"><label>Rows per page<select aria-label="Purchase orders per page" value={pageSize} onChange={event => setPagination({ projectId, search, page: 1, size: Number(event.target.value) })}>{[20, 50, 100, 200].map(size => <option key={size}>{size}</option>)}</select></label><span aria-live="polite">{orders.isFetching ? 'Loading...' : `${total ? (page - 1) * pageSize + 1 : 0}–${total ? (page - 1) * pageSize + (orders.data?.items.length || 0) : 0} of ${total}`}</span><div className="register-page-controls"><button className="icon-button" title="First page" aria-label="First page" disabled={page <= 1 || orders.isFetching} onClick={() => changePage(1)}><ChevronsLeft size={16} /></button><button className="icon-button" title="Previous page" aria-label="Previous page" disabled={page <= 1 || orders.isFetching} onClick={() => changePage(page - 1)}><ChevronLeft size={16} /></button><span>Page {page} of {pages}</span><button className="icon-button" title="Next page" aria-label="Next page" disabled={page >= pages || orders.isFetching || !!orders.error} onClick={() => changePage(page + 1)}><ChevronRight size={16} /></button><button className="icon-button" title="Last page" aria-label="Last page" disabled={page >= pages || orders.isFetching || !!orders.error} onClick={() => changePage(pages)}><ChevronsRight size={16} /></button></div></div><QueryError error={orders.error} onRetry={() => void orders.refetch()} /></section></>
}

export function OrderTable({ orders, loading, compact = false, onEdit, onPayment, onHistory }: { orders: PurchaseOrder[]; loading: boolean; compact?: boolean; onEdit?: (order: PurchaseOrder) => void; onPayment?: (order: PurchaseOrder) => void; onHistory?: (order: PurchaseOrder) => void }) { return <div className="table-scroll"><table className="data-table"><thead><tr><th>PO number</th><th>Vendor</th><th>Item</th><th>Order date</th><th className="numeric">Total</th><th className="numeric">Paid</th><th className="numeric">Balance</th>{!compact && <th>Actions</th>}</tr></thead><tbody>{loading ? <tr><td colSpan={compact ? 7 : 8}><div className="loading-line" /></td></tr> : orders.length ? orders.map(order => <tr key={order.id}><td><span className="po-number">{order.number}</span><StatusMark status={order.payment_status} /></td><td>{order.vendor.name}</td><td><span className="item-cell">{order.item_names.join(', ') || '—'}</span></td><td>{dateLabel(order.order_date)}</td><td className="numeric">{currency(order.total, order.currency)}</td><td className="numeric">{currency(order.paid_to_date, order.currency)}</td><td className={`numeric ${order.balance === '0.00' ? 'settled-text' : 'balance-text'}`}>{currency(order.balance, order.currency)}</td>{!compact && <td><div className="row-actions"><span className="row-action-tooltip" data-tooltip={order.can_edit ? 'Edit purchase order' : 'Fully paid; editing is disabled'}><button className="icon-button" title={order.can_edit ? 'Edit purchase order' : 'Fully paid; editing is disabled'} aria-label={order.can_edit ? 'Edit purchase order' : 'Fully paid; editing is disabled'} disabled={!order.can_edit} onClick={() => onEdit?.(order)}><Settings2 size={15} /></button></span><span className="row-action-tooltip" data-tooltip={order.can_add_payment ? 'Add payment' : 'Fully paid; no balance remains'}><button className="icon-button" title={order.can_add_payment ? 'Add payment' : 'Fully paid; no balance remains'} aria-label={order.can_add_payment ? 'Add payment' : 'Fully paid; no balance remains'} disabled={!order.can_add_payment} onClick={() => onPayment?.(order)}><Plus size={16} /></button></span><span className="row-action-tooltip" data-tooltip={`Payment history for ${order.number}`}><button className="icon-button" title={`Payment history for ${order.number}`} aria-label={`Payment history for ${order.number}`} onClick={() => onHistory?.(order)}><Clock3 size={15} /></button></span></div></td>}</tr>) : <tr><td colSpan={compact ? 7 : 8}><EmptyState title="No purchase orders" note="Create an order to start tracking vendor commitments." /></td></tr>}</tbody></table></div> }

export function StatusMark({ status }: { status: string }) { const cls = status === 'Paid' ? 'paid' : status === 'Partially paid' ? 'partial' : 'unpaid'; return <span className={`payment-mark ${cls}`} title={status} aria-label={status}>{status === 'Paid' ? '✓' : status === 'Partially paid' ? '◐' : '!'}</span> }

export function PaymentHistory({ projectId, order }: { projectId: string; order: PurchaseOrder }) {
  const [page, setPage] = useState(1)
  const pageSize = 5
  const payments = useQuery({ queryKey: ['project', projectId, 'po', order.id, 'payments', page, pageSize], queryFn: () => api.payments(projectId, order.id, page, pageSize) })
  const total = payments.data?.total || 0
  const pages = Math.max(1, Math.ceil(total / pageSize))
  return <div className="payment-history-dialog"><div className="payment-summary history-summary"><div className="history-order-identity"><span>Purchase order</span><strong>{order.number}</strong><small>{order.vendor.name}</small></div><div className="history-total"><span>Total</span><strong>{currency(order.total, order.currency)}</strong></div><div className="history-paid"><span>Paid</span><strong>{currency(order.paid_to_date, order.currency)}</strong></div><div className="history-balance"><span>Balance</span><strong>{currency(order.balance, order.currency)}</strong></div></div><div className="table-scroll"><table className="data-table payment-history-table"><thead><tr><th>Payment date</th><th className="numeric">Amount</th><th>Mode</th><th>Reference</th><th>Comment</th><th>Recorded by</th></tr></thead><tbody>{payments.isLoading ? <tr><td colSpan={6}><div className="loading-line" /></td></tr> : payments.data?.items.length ? payments.data.items.map(payment => <tr key={payment.id}><td>{dateLabel(payment.payment_date)}</td><td className="numeric">{currency(payment.amount, order.currency)}</td><td>{payment.payment_mode || 'Other'}</td><td>{payment.reference || '—'}</td><td className="overview-comment">{payment.comment || '—'}</td><td>{payment.recorded_by.name}</td></tr>) : <tr><td colSpan={6}><EmptyState title="No payments recorded" note="Installments will appear here after they are saved." /></td></tr>}</tbody></table></div>{total > pageSize && <div className="register-pagination"><span>{(page - 1) * pageSize + 1}–{Math.min(page * pageSize, total)} of {total}</span><div className="register-page-controls"><button className="icon-button" title="Previous payments" aria-label="Previous payments" disabled={page <= 1 || payments.isFetching} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></button><span>Page {page} of {pages}</span><button className="icon-button" title="Next payments" aria-label="Next payments" disabled={page >= pages || payments.isFetching} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></button></div></div>}<QueryError error={payments.error} onRetry={() => void payments.refetch()} /></div>
}

export function Inventory({ projectId, search, setSearch }: { projectId: string; search: string; setSearch: (value: string) => void }) {
  const stock = useQuery({ queryKey: ['project', projectId, 'inventory', { search }], queryFn: () => api.inventory(projectId) })
  const summary = useQuery({ queryKey: ['project', projectId, 'inventory-summary'], queryFn: () => api.inventorySummary(projectId) })
  const rows = (stock.data?.items || []).filter(item => `${item.item.name} ${item.item.sku} ${item.item.category}`.toLowerCase().includes(search.toLowerCase()))
  return <><PageTitle eyebrow="MATERIALS" title="Inventory" subtitle="Procured items and received project stock" /><div className="kpi-grid three"><Kpi label="Project items" value={String(summary.data?.catalog_item_count ?? '—')} note="Linked from procurement" icon={<Package size={17} />} loading={summary.isLoading} /><Kpi label="Items in stock" value={String(summary.data?.stocked_item_count ?? '—')} note="With available quantity" icon={<BadgeCheck size={17} />} loading={summary.isLoading} /><Kpi label="Stock valuation" value={summary.data?.valuation_amount ? currency(summary.data.valuation_amount, summary.data.currency) : 'Not valued'} note="Finance method not configured" icon={<CircleDollarSign size={17} />} /></div><section className="panel table-panel"><PanelHeading title="Project material register" meta="Ordered stock is separate from received stock" action={<div className="search-wrap"><Search size={16} /><input placeholder="Search materials" value={search} onChange={event => setSearch(event.target.value)} /></div>} /><div className="table-scroll"><table className="data-table"><thead><tr><th>Item ID</th><th>Material</th><th>Category</th><th className="numeric">Ordered</th><th className="numeric">Received</th><th className="numeric">Consumed</th><th className="numeric">Available</th></tr></thead><tbody>{stock.isLoading ? <tr><td colSpan={7}><div className="loading-line" /></td></tr> : rows.length ? rows.map(row => <InventoryTableRow key={row.item.id} row={row} />) : <tr><td colSpan={7}><EmptyState title="No inventory items" note="Items are added here when purchase orders are created." /></td></tr>}</tbody></table></div><QueryError error={stock.error} onRetry={() => void stock.refetch()} /></section></>
}

export function InventoryTableRow({ row }: { row: InventoryRow }) { return <tr><td className="muted-cell">{row.item.sku}</td><td className="strong-cell">{row.item.name}</td><td>{row.item.category}</td><td className="numeric">{row.ordered_quantity} {row.item.unit_of_measure}</td><td className="numeric">{row.received_quantity} {row.item.unit_of_measure}</td><td className="numeric">{row.consumed_quantity} {row.item.unit_of_measure}</td><td className="numeric strong-cell">{row.available_quantity} {row.item.unit_of_measure}</td></tr> }

export function Billing({ projectId, onNew }: { projectId: string; onNew: () => void }) {
  const summary = useQuery({ queryKey: ['project', projectId, 'billing-summary'], queryFn: () => api.billingSummary(projectId) })
  const billings = useQuery({ queryKey: ['project', projectId, 'billings'], queryFn: () => api.billings(projectId) })
  const data = summary.data
  return <><PageTitle eyebrow="CLIENT REVENUE" title="Progress billing" subtitle="Applications, contract and client collections" action={<button className="button-primary" onClick={onNew}><Plus size={16} />New application</button>} /><div className="kpi-grid four"><Kpi label="Approved contract" value={currency(data?.approved_contract_value, data?.currency)} note="Original plus approved changes" icon={<FileText size={17} />} loading={summary.isLoading} /><Kpi label="Billed to date" value={currency(data?.billed_work, data?.currency)} note="Submitted applications" icon={<ArrowUpRight size={17} />} loading={summary.isLoading} /><Kpi label="Retainage held" value={currency(data?.retainage_held, data?.currency)} note="Based on approved billings" icon={<Clock3 size={17} />} loading={summary.isLoading} /><Kpi label="Awaiting payment" value={currency(data?.outstanding_invoices, data?.currency)} note="Outstanding invoices" icon={<CircleDollarSign size={17} />} loading={summary.isLoading} /></div><section className="panel table-panel"><PanelHeading title="Billing applications" meta="Client-side applications and current due" /><div className="table-scroll"><table className="data-table"><thead><tr><th>Application</th><th>Work completed</th><th>Submitted</th><th className="numeric">Current due</th><th>Status</th></tr></thead><tbody>{billings.isLoading ? <tr><td colSpan={5}><div className="loading-line" /></td></tr> : billings.data?.items.length ? billings.data.items.map(row => <tr key={row.id}><td className="strong-cell">{row.application_number}</td><td>{row.description}</td><td>{dateLabel(row.period_start)}</td><td className="numeric">{currency(row.net_billable, row.currency)}</td><td><span className="status-pill planning">{row.status}</span></td></tr>) : <tr><td colSpan={5}><EmptyState title="No billing applications" note="Submitted applications will appear here." /></td></tr>}</tbody></table></div><QueryError error={billings.error} onRetry={() => void billings.refetch()} /></section></>
}

export function Attendance({ projectId, search, setSearch, onNew }: { projectId: string; search: string; setSearch: (value: string) => void; onNew: () => void }) {
  const cards = useQuery({ queryKey: ['project', projectId, 'timecards'], queryFn: () => api.timecards(projectId) })
  const summary = useQuery({ queryKey: ['project', projectId, 'attendance-summary'], queryFn: () => api.attendanceSummary(projectId) })
  const rows = (cards.data?.items || []).filter(card => `${card.employee.name} ${card.cost_code.name}`.toLowerCase().includes(search.toLowerCase()))
  return <><PageTitle eyebrow="FIELD OPERATIONS" title="Attendance & labor" subtitle="Timecards mapped to project cost codes" action={<button className="button-primary" onClick={onNew}><Plus size={16} />Log hours</button>} /><div className="kpi-grid four"><Kpi label="Hours logged" value={`${summary.data?.regular_hours ?? '—'} h`} note="Selected date range" icon={<Clock3 size={17} />} loading={summary.isLoading} /><Kpi label="Labor cost" value={summary.data?.labor_cost ? currency(summary.data.labor_cost, summary.data.currency) : '—'} note="Approved rate capture" icon={<CircleDollarSign size={17} />} loading={summary.isLoading} /><Kpi label="Pending approval" value={String(summary.data?.pending_count ?? '—')} note="Awaiting supervisor" icon={<Clock3 size={17} />} loading={summary.isLoading} /><Kpi label="Approved timecards" value={String(summary.data?.approved_count ?? '—')} note="Included in labor cost" icon={<Check size={17} />} loading={summary.isLoading} /></div><section className="panel table-panel"><PanelHeading title="Timecard log" meta="Newest work dates first" action={<div className="search-wrap"><Search size={16} /><input placeholder="Search employee or code" value={search} onChange={event => setSearch(event.target.value)} /></div>} /><div className="table-scroll"><table className="data-table"><thead><tr><th>Employee</th><th>Cost code</th><th>Work date</th><th className="numeric">Hours</th><th className="numeric">Labor cost</th><th>Status</th></tr></thead><tbody>{cards.isLoading ? <tr><td colSpan={6}><div className="loading-line" /></td></tr> : rows.length ? rows.map(card => <TimecardRow card={card} key={card.id} currencyCode={summary.data?.currency || 'INR'} />) : <tr><td colSpan={6}><EmptyState title="No timecards" note="Log hours to begin the project's labor record." /></td></tr>}</tbody></table></div><QueryError error={cards.error} onRetry={() => void cards.refetch()} /></section></>
}

export function TimecardRow({ card, currencyCode }: { card: Timecard; currencyCode: string }) { return <tr><td className="strong-cell">{card.employee.name}</td><td>{card.cost_code.name}</td><td>{dateLabel(card.work_date)}</td><td className="numeric">{card.regular_hours} h</td><td className="numeric">{card.labor_cost ? currency(card.labor_cost, currencyCode) : '—'}</td><td><span className={`status-pill ${card.status === 'Approved' ? 'complete' : 'planning'}`}>{card.status}</span></td></tr> }

export function ModalFrame({ title, onClose, children, className = '' }: { title: string; onClose: () => void; children: React.ReactNode; dismissOnBackdrop?: boolean; className?: string }) {
  const dialog = useRef<HTMLElement>(null)
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || document.querySelectorAll('[role="dialog"]').item(document.querySelectorAll('[role="dialog"]').length - 1) !== dialog.current) return
      event.preventDefault()
      onClose()
    }
    document.addEventListener('keydown', handleEscape)
    return () => document.removeEventListener('keydown', handleEscape)
  }, [onClose])
  return <div className="modal-backdrop"><section ref={dialog} className={`modal ${className}`} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div className="modal-heading"><div><span className="eyebrow">VRIDHI WORKSPACE</span><h2 id="dialog-title">{title}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={18} /></button></div>{children}</section></div>
}

export function ProjectForm({ csrf, onSaved, onCancel }: { csrf: string; onSaved: (project: Project) => void; onCancel: () => void }) {
  const [form, setForm] = useState({ name: '', location: '', baseline_budget: '', contract_value: '', start_date: todayISO, status: 'Planning' as 'Planning' | 'Active', plan_comment: '' })
  const [planDocument, setPlanDocument] = useState<File | null>(null)
  const [fileError, setFileError] = useState('')
  const fileInput = useRef<HTMLInputElement>(null)
  const mutation = useMutation({ mutationFn: () => api.createProject({ ...form, plan_document: planDocument }, csrf), onSuccess: onSaved })
  const acceptFile = (file?: File) => {
    if (!file) return
    const allowed = /\.(pdf|png|jpe?g|docx)$/i.test(file.name)
    if (!allowed) { setFileError('Choose a PDF, PNG, JPG, or DOCX file.'); return }
    if (file.size > 10 * 1024 * 1024) { setFileError('The plan file must be 10 MB or smaller.'); return }
    setFileError('')
    setPlanDocument(file)
  }
  const handlePaste = (event: ClipboardEvent<HTMLDivElement>) => {
    const image = Array.from(event.clipboardData.items).find(item => item.type.startsWith('image/'))
    const blob = image?.getAsFile()
    if (!blob) return
    event.preventDefault()
    const extension = blob.type === 'image/jpeg' ? 'jpg' : blob.type.split('/')[1] || 'png'
    acceptFile(new File([blob], `pasted-plan-${Date.now()}.${extension}`, { type: blob.type }))
  }
  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    acceptFile(event.dataTransfer.files[0])
  }
  return <form className="form-grid" onSubmit={event => { event.preventDefault(); mutation.mutate() }}>
    <label className="field full">Project name<input required maxLength={160} value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} placeholder="e.g. Riverside Medical Center" /></label>
    <label className="field full">Location<input required value={form.location} onChange={event => setForm({ ...form, location: event.target.value })} placeholder="City, state or region" /></label>
    <label className="field">Approved budget (₹)<input required type="number" min="0" step="0.01" value={form.baseline_budget} onChange={event => setForm({ ...form, baseline_budget: event.target.value })} /></label>
    <label className="field">Contract value (₹)<input required type="number" min="0" step="0.01" value={form.contract_value} onChange={event => setForm({ ...form, contract_value: event.target.value })} /></label>
    <label className="field">Start date<input required type="date" value={form.start_date} onChange={event => setForm({ ...form, start_date: event.target.value })} /></label>
    <label className="field">Project status<select value={form.status} onChange={event => setForm({ ...form, status: event.target.value as 'Planning' | 'Active' })}><option value="Planning">Planning</option><option value="Active">Active</option></select></label>
    <label className="field full">Initial plan approval document (optional)<div className="native-file-row" tabIndex={0} onPaste={handlePaste} onDragOver={event => event.preventDefault()} onDrop={handleDrop} aria-label="Choose, paste, or drop an initial plan document"><input ref={fileInput} type="file" accept=".pdf,.png,.jpg,.jpeg,.docx" onChange={event => acceptFile(event.target.files?.[0])} />{planDocument && <span className="selected-file-name">{planDocument.name} · {(planDocument.size / (1024 * 1024)).toFixed(2)} MB</span>}</div><small className="field-hint">PDF, PNG, JPG, or DOCX · max 10 MB · paste an image or drop a file here</small></label>
    {fileError && <div className="form-error full">{fileError}</div>}
    <label className="field full">Document comment<textarea maxLength={500} value={form.plan_comment} onChange={event => setForm({ ...form, plan_comment: event.target.value })} placeholder="Add a note about this approval document (optional)" /></label>
    <MutationError error={mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending} submit="Create project" />
  </form>
}

export function POForm({ projectId, csrf, order, onSaved, onCancel }: { projectId: string; csrf: string; order: PurchaseOrder | null; onSaved: () => void; onCancel: () => void }) {
  const vendors = useQuery({ queryKey: ['reference', 'vendors'], queryFn: api.vendors })
  const materials = useQuery({ queryKey: ['reference', 'items'], queryFn: api.inventoryItems })
  const detail = useQuery({ queryKey: ['project', projectId, 'po', order?.id], queryFn: () => api.purchaseOrder(projectId, order!.id), enabled: !!order })
  const [vendor, setVendor] = useState('')
  const [item, setItem] = useState('')
  const [quantity, setQuantity] = useState('1')
  const [price, setPrice] = useState('')
  const [orderDate, setOrderDate] = useState(todayISO)
  const [paid, setPaid] = useState('0')
  const [paymentMode, setPaymentMode] = useState<'Gpay' | 'Bank transfer' | 'Cash' | 'Other'>('Cash')
  const [paymentComment, setPaymentComment] = useState('')
  const [orderImage, setOrderImage] = useState<File | null>(null)
  const [imageError, setImageError] = useState('')
  const matchName = (input: string, choices: { name: string }[] = []) => choices.find(choice => choice.name.toLocaleLowerCase() === input.trim().toLocaleLowerCase())?.name || input
  const vendorSuggestions = vendor.trim() ? (vendors.data?.items || []).filter(value => value.name.toLocaleLowerCase().includes(vendor.trim().toLocaleLowerCase())) : []
  const materialSuggestions = item.trim() ? (materials.data?.items || []).filter(value => value.name.toLocaleLowerCase().includes(item.trim().toLocaleLowerCase())) : []
  useEffect(() => { if (detail.data) { setVendor(detail.data.vendor.name); setItem(detail.data.lines[0]?.item.name || ''); setQuantity(detail.data.lines[0]?.quantity || '1'); setPrice(detail.data.lines[0]?.unit_price || ''); setOrderDate(detail.data.order_date) } }, [detail.data])
  const total = Math.round(Number(quantity || 0) * Number(price || 0) * 100) / 100
  const paidAmount = order ? Number(detail.data?.paid_to_date || order.paid_to_date) : Number(paid || 0)
  const balance = total - paidAmount
  const paymentInvalid = !Number.isFinite(total) || !Number.isFinite(paidAmount) || paidAmount < 0 || paidAmount > total
  const mutation = useMutation({ mutationFn: () => {
    const vendorName = matchName(vendor, vendors.data?.items)
    const materialName = matchName(item, materials.data?.items)
    return api.savePurchaseOrder(projectId, {
      vendor_name: vendorName.trim(), order_date: orderDate,
      lines: [{ item_name: materialName.trim(), description: materialName.trim(), quantity, unit_price: price }],
      ...(!order ? { paid_amount: paid || '0', payment_mode: paymentMode, payment_comment: paymentComment } : {}),
    }, csrf, order ? { id: order.id, version: detail.data?.version ?? order.version } : undefined, orderImage)
  }, onSuccess: onSaved })
  return <form className="form-grid" onSubmit={event => { event.preventDefault(); if (!paymentInvalid) mutation.mutate() }}>
    <label className="field full">Vendor<input required maxLength={160} list="purchase-order-vendor-suggestions" value={vendor} onChange={event => setVendor(matchName(event.target.value, vendors.data?.items))} onBlur={() => setVendor(matchName(vendor, vendors.data?.items))} placeholder="Enter vendor name" /><datalist id="purchase-order-vendor-suggestions">{vendorSuggestions.map(value => <option key={value.id} value={value.name} />)}</datalist></label>
    <label className="field full">Material<input required maxLength={180} list="purchase-order-material-suggestions" value={item} onChange={event => setItem(matchName(event.target.value, materials.data?.items))} onBlur={() => setItem(matchName(item, materials.data?.items))} placeholder="Enter material or service" /><datalist id="purchase-order-material-suggestions">{materialSuggestions.map(value => <option key={value.id} value={value.name} />)}</datalist></label>
    {order && detail.data?.image?.available && <div className="field full"><span>Attached image</span><a href={detail.data.image.url} target="_blank" rel="noreferrer">{detail.data.image.filename}</a></div>}
    {!order && <label className="field full">Receipt (Optional)<input type="file" accept="image/png,image/jpeg,image/webp" onChange={event => { const file = event.target.files?.[0]; if (!file) { setOrderImage(null); setImageError(''); return } if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) { setOrderImage(null); setImageError('Choose a PNG, JPG, or WEBP image.'); return } if (!file.size || file.size > 10 * 1024 * 1024) { setOrderImage(null); setImageError('Choose a non-empty image no larger than 10 MB.'); return } setOrderImage(file); setImageError('') }} />{orderImage && <small className="field-hint">{orderImage.name} · {(orderImage.size / (1024 * 1024)).toFixed(2)} MB</small>}{imageError && <span className="form-error" role="alert">{imageError}</span>}</label>}
    <label className="field">Quantity<input required type="number" min="0.01" step="0.01" value={quantity} onChange={event => setQuantity(event.target.value)} /></label>
    <label className="field">Unit price (₹)<input required type="number" min="0" step="0.01" value={price} onChange={event => setPrice(event.target.value)} /></label>
    <label className="field full">Total purchase price (₹)<input readOnly value={Number.isFinite(total) ? total.toFixed(2) : '0.00'} /></label>
    <label className="field">Paid (₹)<input type="number" min="0" max={total} step="0.01" readOnly={!!order} aria-invalid={paymentInvalid} aria-describedby={paymentInvalid ? 'po-payment-error' : undefined} value={order ? paidAmount.toFixed(2) : paid} onChange={event => setPaid(event.target.value)} />{paymentInvalid && <span id="po-payment-error" className="form-error" role="alert">{paidAmount > total ? 'Paid amount cannot exceed the total purchase price.' : 'Enter a valid nonnegative paid amount.'}</span>}</label>
    <label className="field">Balance (₹)<input readOnly value={Number.isFinite(balance) ? balance.toFixed(2) : '0.00'} /></label>
    <label className="field">Order date<input required type="date" value={orderDate} onChange={event => setOrderDate(event.target.value)} /></label>
    {!order && <><label className="field">Payment mode<select value={paymentMode} onChange={event => setPaymentMode(event.target.value as typeof paymentMode)}><option>Gpay</option><option>Bank transfer</option><option>Cash</option><option>Other</option></select></label><label className="field full">Payment reference / comment<textarea maxLength={500} value={paymentComment} onChange={event => setPaymentComment(event.target.value)} placeholder="Transaction reference number or payment feedback" /></label></>}
    <MutationError error={vendors.error || materials.error || detail.error || mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending || detail.isLoading || vendors.isLoading || materials.isLoading} disabled={paymentInvalid || !vendor.trim() || !item.trim() || !!imageError} submit={order ? 'Save changes' : 'Create purchase order'} />
  </form>
}

export function PaymentForm({ projectId, csrf, order, onSaved, onCancel }: { projectId: string; csrf: string; order: PurchaseOrder; onSaved: () => void; onCancel: () => void }) { const detail = useQuery({ queryKey: ['project', projectId, 'po', order.id, 'detail'], queryFn: () => api.purchaseOrder(projectId, order.id) }); const [amount, setAmount] = useState(''); const [paymentDate, setPaymentDate] = useState(todayISO); const [paymentMode, setPaymentMode] = useState<'Gpay' | 'Bank transfer' | 'Cash' | 'Other'>('Cash'); const [reference, setReference] = useState(''); const [comment, setComment] = useState(''); const [idempotencyKey] = useState(() => crypto.randomUUID()); const currentBalance = Number(detail.data?.balance ?? order.balance); const enteredAmount = Number(amount || 0); const balanceAfterPayment = currentBalance - enteredAmount; const paymentInvalid = !amount || enteredAmount <= 0 || enteredAmount > currentBalance; const mutation = useMutation({ mutationFn: (token: string) => api.addPayment(projectId, order.id, { amount, payment_date: paymentDate, payment_mode: paymentMode, reference, comment }, token, idempotencyKey), onSuccess: onSaved }); return <form className="form-grid" onSubmit={event => { event.preventDefault(); if (!paymentInvalid) mutation.mutate(csrf) }}><div className="payment-summary full"><span>{order.number} · {order.vendor.name}</span><strong>Current balance {currency(currentBalance, order.currency)}</strong></div><label className="field">Payment amount (₹)<input autoFocus required type="number" min="0.01" max={currentBalance} step="0.01" value={amount} aria-invalid={paymentInvalid && !!amount} onChange={event => setAmount(event.target.value)} /></label><label className="field">Balance after payment (₹)<input readOnly value={currency(Math.max(0, balanceAfterPayment), order.currency)} /></label>{paymentInvalid && !!amount && <div className="form-error full" role="alert">Payment amount cannot exceed the current balance.</div>}<label className="field">Payment date<input required type="date" value={paymentDate} onChange={event => setPaymentDate(event.target.value)} /></label><label className="field">Mode of payment<select value={paymentMode} onChange={event => setPaymentMode(event.target.value as typeof paymentMode)}><option>Gpay</option><option>Bank transfer</option><option>Cash</option><option>Other</option></select></label><label className="field full">Reference<input maxLength={100} value={reference} onChange={event => setReference(event.target.value)} placeholder="Payment reference number" /></label><label className="field full">Comment<textarea maxLength={500} value={comment} onChange={event => setComment(event.target.value)} placeholder="Optional payment feedback" /></label><MutationError error={detail.error || mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending || detail.isLoading} disabled={paymentInvalid} submit="Record payment" /></form> }

export function TimecardForm({ projectId, csrf, onSaved, onCancel }: { projectId: string; csrf: string; onSaved: () => void; onCancel: () => void }) { const [form, setForm] = useState({ employee_name: '', cost_code: 'Concrete', work_date: todayISO, regular_hours: '8', hourly_rate: '34' }); const mutation = useMutation({ mutationFn: () => api.createTimecard(projectId, form, csrf), onSuccess: onSaved }); return <form className="form-grid" onSubmit={event => { event.preventDefault(); mutation.mutate() }}><label className="field full">Employee<input required value={form.employee_name} onChange={event => setForm({ ...form, employee_name: event.target.value })} placeholder="Employee name" /></label><label className="field">Work date<input required type="date" value={form.work_date} onChange={event => setForm({ ...form, work_date: event.target.value })} /></label><label className="field">Cost code<select value={form.cost_code} onChange={event => setForm({ ...form, cost_code: event.target.value })}>{['Concrete', 'Framing', 'Electrical', 'Sitework', 'Plumbing'].map(code => <option key={code}>{code}</option>)}</select></label><label className="field">Hours<input required type="number" min="0.25" max="24" step="0.25" value={form.regular_hours} onChange={event => setForm({ ...form, regular_hours: event.target.value })} /></label><label className="field">Hourly rate (₹)<input required type="number" min="0" step="0.01" value={form.hourly_rate} onChange={event => setForm({ ...form, hourly_rate: event.target.value })} /></label><MutationError error={mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending} submit="Submit timecard" /></form> }

export function BillingForm({ projectId, csrf, onSaved, onCancel }: { projectId: string; csrf: string; onSaved: () => void; onCancel: () => void }) { const [form, setForm] = useState({ description: '', submitted_date: todayISO, amount: '' }); const mutation = useMutation({ mutationFn: () => api.createBilling(projectId, form, csrf), onSuccess: onSaved }); return <form className="form-grid" onSubmit={event => { event.preventDefault(); mutation.mutate() }}><label className="field full">Work completed<input required value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} placeholder="Description of this application" /></label><label className="field">Submitted date<input required type="date" value={form.submitted_date} onChange={event => setForm({ ...form, submitted_date: event.target.value })} /></label><label className="field">Current due (₹)<input required type="number" min="0.01" step="0.01" value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /></label><div className="form-note full">This records a submitted application. Invoice issuance and approvals are separate planned workflows.</div><MutationError error={mutation.error} /><FormActions onCancel={onCancel} busy={mutation.isPending} submit="Submit application" /></form> }

